-- Clean bootstrap 011: procurement and dual currency.
CREATE TABLE IF NOT EXISTS public.suppliers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,contact_name text,email text,phone text,address text,preferred_currency text NOT NULL DEFAULT 'CDF' CHECK(preferred_currency IN('CDF','USD')),is_active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.purchases(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),purchase_number text NOT NULL UNIQUE,supplier_id uuid NOT NULL REFERENCES public.suppliers(id) ON DELETE RESTRICT,buyer_id uuid REFERENCES auth.users(id) ON DELETE SET NULL,created_by uuid REFERENCES auth.users(id) ON DELETE SET NULL,status text NOT NULL DEFAULT 'draft',currency text NOT NULL DEFAULT 'CDF' CHECK(currency IN('CDF','USD')),exchange_rate numeric(18,6) NOT NULL DEFAULT 1,total_amount numeric(18,2) NOT NULL DEFAULT 0,ordered_at timestamptz NOT NULL DEFAULT now(),due_date timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.purchase_order_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),purchase_id uuid NOT NULL REFERENCES public.purchases(id) ON DELETE CASCADE,product_id uuid NOT NULL REFERENCES public.products(id) ON DELETE RESTRICT,quantity integer NOT NULL CHECK(quantity>0),unit_cost numeric(18,2) NOT NULL CHECK(unit_cost>=0),line_total numeric(18,2) NOT NULL CHECK(line_total>=0));
ALTER TABLE public.suppliers ENABLE ROW LEVEL SECURITY; ALTER TABLE public.purchases ENABLE ROW LEVEL SECURITY; ALTER TABLE public.purchase_order_items ENABLE ROW LEVEL SECURITY;
